namespace M1.Ax.Erp.JobSchedule.ShopLoadExplorer;

public class QueryBuilder
{
	public string BuildShopLoadQuery()
	{
		return "SELECT s.sxdscheduletreeid, s.sxdschedulebranchid, s.sxdscheduletaskid, s.sxdresourceuniqueid, \r\n                           CASE WHEN wcm.xaqworkcentermachineid IS NULL AND S.sxdresourceuniqueid IS NULL THEN '0' \r\n                           ELSE wcm.xaqworkcentermachineid END AS xaqWorkCenterMachineID,                           \r\n                           CASE WHEN wcm.xaqworkcentermachineid IS NULL AND sxdresourceuniqueid IS NULL THEN '<i>Infinite Capacity</i>' \r\n                           ELSE wcm.xaqdescription END AS xaqDescription, S.sxdscheduleresourcelaneid, S.sxddatetype, S.sxdstartminute, \r\n                           S.sxdstartactualdatetime, S.sxdendactualdatetime, S.sxdminutes, S.sxdendminute, \r\n                           scheduletrees.sxtsourceuniqueid, scheduletrees.sxtuniqueid, scheduletrees.sxttype, \r\n                           wc.xawproductiondepartmentid, wc.xawdescription, wc.xawnumberofmachines, \r\n                           st.sxkprocessid AS xawProcessID, st.sxkplantid AS xawPlantID, \r\n                           PD.xaeproductiondepartmentid, PD.xaedescription, COALESCE(wcm.xaqworkcenterid, jmoworkcenterid) AS xaqWorkCenterID, \r\n                           J.jmpjobid, JO.jmoactualproductionhours, \r\n                           CASE WHEN S.sxddatetype = '2' THEN JO.jmoactualsetuphours * 60 \r\n                                WHEN S.sxddatetype = '3' THEN JO.jmoactualproductionhours * 60 \r\n                           ELSE S.sxdminutes END AS actualMinutes, \r\n                           J.jmpuniqueid, J.jmpproductionduedate, J.jmpcustomerorganizationid, J.jmppartid, J.jmppartrevisionid, \r\n                           J.jmppartshortdescription, J.jmpjobpriorityid, J.jmpschedulelocked, J.jmpreleasedtofloor, J.jmponhold, J.jmpprojectid, \r\n                           A.jmajobassemblyid, A.jmapartid, A.jmapartrevisionid, A.jmapartshortdescription, A.jmaproductioncomplete, \r\n                           CASE WHEN jmoactualproductionhours > 0 THEN '1' \r\n                           ELSE jmosetupcomplete END AS setupComplete, \r\n                           JO.jmosetuphours, JO.jmostarthour, JO.jmoduehour, JO.jmoEstimatedproductionhours, JO.jmostartdate, JO.jmoduedate, Jo.jmojoboperationid, \r\n                           sxduniqueid, Isnull(O.cmoname, '') AS cmoName \r\n                    FROM   scheduletrees \r\n                           INNER JOIN scheduleallocations s ON S.sxdscheduletreeid = scheduletrees.sxtscheduletreeid \r\n                           INNER JOIN workcenters wc ON S.sxdgroupuniqueid = wc.xawuniqueid \r\n                           INNER JOIN scheduletasks st ON S.sxdscheduletreeid = st.sxkscheduletreeid \r\n                           AND S.sxdschedulebranchid = st.sxkschedulebranchid AND S.sxdscheduletaskid = st.sxkscheduletaskid \r\n                           LEFT JOIN workcentermachines wcm ON S.sxdresourceuniqueid = wcm.xaquniqueid \r\n                           INNER JOIN jobs AS J ON scheduletrees.sxtsourceuniqueid = J.jmpuniqueid \r\n                           AND jmpclosed = 0 AND jmpplanningcomplete = 1 \r\n                           INNER JOIN productiondepartments AS PD ON PD.xaeproductiondepartmentid = wc.xawproductiondepartmentid \r\n                           INNER JOIN jobassemblies AS A ON A.jmajobid = J.jmpjobid AND A.jmajobassemblyid = S.sxdschedulebranchid \r\n                           INNER JOIN joboperations AS JO ON JO.jmoproductioncomplete = 0 \r\n                           AND JO.jmojobid = J.jmpjobid AND JO.jmojobassemblyid = A.jmajobassemblyid AND JO.jmojoboperationid = S.sxdscheduletaskid \r\n                           LEFT OUTER JOIN organizations AS O ON jmpCustomerOrganizationID = O.cmoOrganizationID \r\n                           WHERE scheduletrees.sxttype = 1 \r\n                           AND S.sxdminutes > 0 \r\n                           AND S.sxddatetype IN ( 2, 3 ) \r\n\t\t\t\t\t\t   AND ({0}) \r\n\t\t\t\t\t\t ORDER BY {1}";
	}
}
